import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"行动组导览","description":"从「读世界」跨到「写世界」的原语层：工具调用契约与工具执行工程——动作如何被描述、被校验、被安全地执行。","frontmatter":{"title":"行动组导览","description":"从「读世界」跨到「写世界」的原语层：工具调用契约与工具执行工程——动作如何被描述、被校验、被安全地执行。","domain":"tech","tags":["tech","action","navigation"],"navOrder":49,"topicId":"action-guide","layer":"5","status":"canonical","nodeType":"problem","owner":"learn-ai","externalOwners":[],"prerequisites":[],"next":["tool-calling","tool-execution"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/05-action/index.md","filePath":"zh/tech/05-action/index.md","lastUpdated":1791123418000}'),i={name:"zh/tech/05-action/index.md"};function n(l,t,s,h,d,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="行动组导览" tabindex="-1">行动组导览 <a class="header-anchor" href="#行动组导览" aria-label="Permalink to &quot;行动组导览&quot;">​</a></h1><blockquote><p><strong>所在组</strong>：行动（Action · 写世界） ｜ <strong>上一组出口</strong>：能让结果有据可查、可追溯 ｜ <strong>本组出口</strong>：能定义一次受控执行的动作，并让它具备幂等、超时、取消与权限边界</p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：Grounding 组的系统最坏的失败是「给出没有依据的答案」；本组开始，系统会<strong>改变外部世界</strong>——写文件、发消息、下单。最坏的失败从「答错」升级为「做错」，且往往不可逆。因此本组只有两页，共同回答一个问题：<strong>如何让一次动作受控</strong>。</p><table tabindex="0"><thead><tr><th>页面</th><th>回答的问题</th><th>读完你能</th></tr></thead><tbody><tr><td><a href="./tool-calling.html">工具调用契约</a></td><td>模型如何「想调用」一个动作？schema、选择、参数验证</td><td>定义可靠的工具接口契约</td></tr><tr><td><a href="./tool-execution.html">工具执行工程</a></td><td>「实际执行」如何安全？幂等、超时、取消、副作用分级、权限</td><td>落地一个受控执行器</td></tr></tbody></table><p><strong>边界</strong>：本组是单次动作的原语层。多步编排、状态与恢复进入 <a href="./../06-agent-systems/">Agent 系统组</a>；跨边界协议进入 <a href="./../07-interoperability/">互操作组</a>。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><ul><li>想知道模型调工具的<strong>契约</strong>长什么样 → 从 <a href="./tool-calling.html">工具调用契约</a> 进入。</li><li>已经在调工具，但担心<strong>重复执行、卡死、越权</strong> → 直接读 <a href="./tool-execution.html">工具执行工程</a>。</li><li>两页各自自带零密钥可运行 fixture；先跑通再回到正文对照。</li></ul><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>「想调用」与「实际执行」的分离是本组的组织原则，也是安全边界的基础：模型输出只是<strong>意图</strong>（一段结构化参数），执行权完全在你的代码手里。所有安全手段——参数校验、allowlist、幂等键、审批门——都挂在执行侧。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>常见误区：把工具 schema 写得过于宽泛（参数全可选、描述含糊），导致模型侧「想调用」的质量差；以及在执行侧缺少副作用分级，把不可逆操作当成普通调用。两页的开发段各给出对应 runbook。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><ul><li>Beginner：<a href="./tool-calling.html">工具调用契约</a> 概述与决策表。</li><li>Builder：<a href="./tool-execution.html">工具执行工程</a> 的执行循环 fixture。</li><li>Operator：执行工程的 runbook（超时、取消、审批）。</li><li>Researcher：Anthropic / OpenAI 官方 tool use 指南（见两页资料库表）。</li></ul>',14)])])}const f=e(i,[["render",n]]);export{m as __pageData,f as default};
